-- GardenConfig — tunables globales de Defensa del Jardín.
-- DATOS PUROS (RULE-014): sin tipos ni APIs de Roblox; testeable con Lune.
return {
	Lanes = {
		Cantidad = 4,
		SlotsPorLane = 3, -- posiciones de plantado por lane
		CostesDesbloqueo = { 250, 750, 2000 }, -- lanes 2, 3 y 4
	},
	Plataformas = {
		Cantidad = 3,
		CostesDesbloqueo = { 400, 1200 }, -- plataformas 2 y 3
		TickSegundos = 2, -- cada cuánto generan dinero los capturados
	},
	Economia = {
		DineroInicial = 100,
		FactorEscape = 0.5, -- si no hay plataforma libre, el capturado se cobra al 50% al instante
	},
	Combate = {
		IntervaloSpawn = 7, -- segundos entre enemigos por lane activa
		DanoFueraDeCrecimiento = 0, -- una planta no daña hasta terminar de crecer
	},
	Tienda = {
		RestockSegundos = 120,
		StockTamano = 4, -- ofertas simultáneas (v2: el pool creció a 9 plantas)
	},
	Renacimientos = {
		-- Prestigio (v2): reinicia dinero/lanes/plataformas/semillas a cambio de un
		-- multiplicador permanente de ingresos. El requisito es dinero EN MANO.
		CosteBase = 1500, -- coste del primer renacimiento
		CrecimientoCoste = 2.5, -- el coste se multiplica por esto en cada renacimiento
		BonificadorPorRenacer = 0.25, -- +25% de ingresos por renacimiento (acumulativo)
	},
	Dificultad = {
		-- Rampa por renacimiento (v2): el peso de rareza migra desde Común hacia el
		-- resto de rarezas, así los enemigos raros (mejores recompensas) aparecen más.
		ShiftPorRenacer = 4,
		ShiftMaximo = 40,
	},
	Mundo = {
		ParcelasMaximas = 6,
		SeparacionParcelas = 70, -- studs entre parcelas (eje Z)
		LongitudLane = 56, -- studs que recorre un enemigo de punta a punta
	},
}

-- GardenData/Tienda — configuración de la tienda de semillas (datos puros).
return {
	Pool = { "Brotin", "Cardo", "Cactus", "Calabaza", "Carnivora", "Girasol", "Bambu", "Orquidea", "Drago" },
	GarantizarComun = true, -- el stock siempre incluye al menos 1 semilla común (early game jugable)
}
